def solution(base, exp):
    if exp == 0:
        return 1
    elif exp < 0:
        return 1 / solution(base, -exp)
    elif exp % 2 == 0:
        return solution(base * base, exp // 2)
    else:
        return base * solution(base * base, (exp - 1) // 2)

